.message-bubble.system-bubble .content::before,
.message-bubble.is-transfer .content::after,
.message-bubble.is-waimai-request .content::after,
.message-bubble.is-red-packet .content::after,
.message-bubble.is-poll .content::after,
.message-bubble.is-link-share .content::after,
.message-bubble.is-sticker .content::after,
.message-bubble.system-bubble .content::after {
content: none !important;
}
/* 恢复特殊消息的原始样式 */
.message-bubble.is-transfer .content,
.message-bubble.is-waimai-request .content,
.message-bubble.is-red-packet .content,
.message-bubble.is-poll .content,
.message-bubble.is-link-share .content,
.message-bubble.is-sticker .content,
.message-bubble.system-bubble .content {
border-radius: 0 !important;
background: none !important;
border: none !important;
}
/* 图片消息豁免 */
.message-bubble .content:has(>img) {
background: none !important;
border-radius: 0 !important;
box-shadow: none !important;
border: none !important;
}
.message-bubble .content:has(>img)::before,
.message-bubble .content:has(>img)::after {
content: none !important;
}
.message-bubble:has(.content>img)::before {
display: none !important;
}
/* orange消息豁免 */
.message-bubble .content:has(>orange) {
padding:0!important;
border:none!important;
background:none!important;
box-shadow: none !important;
}
.message-bubble:has(.content>orange) {
filter: none !important;
}
.message-bubble:has(.content>orange)::before,
.message-bubble:has(.content>orange)::after {
display:none !important;
}
.message-bubble:has(.content>orange) .content::before,
.message-bubble:has(.content>orange) .content::after {
content: none !important;
}
/* 转账消息专属豁免规则 */
.message-bubble .content:has(.transfer-card),
.message-bubble .content:has([class*="transfer"]),
.message-bubble .content:has([data-type="transfer"]) {
background: none !important;
border: none !important;
border-radius: 0 !important;
padding: 0 !important;
}
.message-bubble .content:has(.transfer-card)::before,
.message-bubble .content:has(.transfer-card)::after,
.message-bubble .content:has([class*="transfer"])::before,
.message-bubble .content:has([class*="transfer"])::after,
.message-bubble .content:has([data-type="transfer"])::before,
.message-bubble .content:has([data-type="transfer"])::after {
content: none !important;
display: none !important;
opacity: 0 !important;
visibility: hidden !important;
}
.message-bubble .content:has(>img:not([class*="avatar"])) {
background: none !important;
border: none !important;
border-radius: 0 !important;
padding: 0 !important;
box-shadow: none !important;
margin: 0 !important;
}
.message-bubble .content:has(>img:not([class*="avatar"]))::before,
.message-bubble .content:has(>img:not([class*="avatar"]))::after {
content: none !important;
display: none !important;
opacity: 0 !important;
visibility: hidden !important;
}
/* 拍一拍样式 */
.message-bubble.system-bubble {
background-color: rgba(255, 255, 255, 0.6) !important;
color: #000000 !important;
line-height: 1.0 !important;
border-radius: 3px !important;
}
/* 状态更新样式 */
#typing-indicator {
background-color: rgba(255, 255, 255, 0.6) !important;
color: #000000 !important;
line-height: 1.1 !important;
border-radius: 3px !important;
}
/* 日期戳样式 */
.date-stamp-wrapper,
.message-wrapper.system-date .date-stamp-bubble,
.date-stamp-wrapper .date-stamp,
.date-stamp-wrapper .date-stamp-bg,
.system-date .date-stamp-bubble,
.system-date .date-stamp-wrapper,
.message-wrapper.system-date,
.system-date,
.date-stamp-bubble,
[class*="date-stamp"],
[class*="system-date"] {
background-color: rgba(255, 255, 255, 0.6) !important;
color: #000000 !important;
border-radius: 3px !important;
line-height: 1.0 !important;
backdrop-filter: none !important;
}
.recalled-message-placeholder {
align-self: center;
padding: 4px 12px;
margin: 5px 0;
background-color: rgba(255, 255, 255, 0.4); /* 半透明白色背景 */
color: #000;
font-size: 12px;
line-height: 1.1 !important;
border-radius: 3px;
text-align: center;
max-width: 80%;
cursor: pointer;
white-space: nowrap;
display: inline-block;
}
/* 响应式设计 */
@media (max-width: 480px) {
#chat-input-actions-top.menu-open,
#chat-input-actions-top:hover {
grid-template-columns: repeat(2, 1fr) !important;
min-width: 200px !important;
}
}
@media (min-width: 768px) {
#chat-input-actions-top.menu-open,
#chat-input-actions-top:hover {
grid-template-columns: repeat(4, 1fr) !important;
min-width: 320px !important;
}
}
/* 只减小系统消息之间的间距 */
.message-wrapper.system-pat + .message-wrapper,
.message-wrapper.system-date + .message-wrapper,
.message-wrapper.system-bubble + .message-wrapper,
.recalled-message-placeholder + .message-wrapper {
margin-top: -10px !important;
}
